const e = $input.first().json || {};
const workflow = e.workflow || {};
const execution = e.execution || {};
// Privacy-first: do not include raw exception messages, payloads, URLs, or stack traces.
const safeName = String(workflow.name || 'Unknown workflow').replace(/[\r\n\t]/g, ' ').slice(0, 100);
const safeId = /^[a-zA-Z0-9_-]{1,64}$/.test(String(execution.id || '')) ? String(execution.id) : null;
return [{ json: { source: 'opsflow-error-alert', workflowName: safeName, executionId: safeId, status: 'WORKFLOW_ERROR', occurredAt: new Date().toISOString(), note: 'Review execution details in your secured n8n instance.' } }];
